{"actions":[{"action":"success_contract","data":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet to 127.0.0.1:6665 reaches the guest login prompt, and leave it running.","required_artifacts":["A running QEMU process using /app/alpine.iso","A reachable telnet service on 127.0.0.1:6665"],"required_behaviors":["QEMU must be started in the background","Port 6665 on localhost must accept telnet connections","Connecting via telnet must present the guest login prompt","The VM must remain running after readiness is confirmed"],"known_invalid_patterns":["Only verifying that QEMU launched without confirming telnet reachability","Only checking that a process exists without confirming the login prompt","Treating file existence or ISO presence as success","Stopping the VM after readiness"],"verification_plan":["Inspect the environment for QEMU/telnet availability and any existing receipts before running equivalent commands","Start QEMU with a serial console redirected to localhost:6665 in the background","Wait until the telnet port is reachable and the login prompt is observable","Record receipt-backed evidence of the running process and prompt reachability"],"finalization_evidence_required":["Receipt showing the QEMU launch command and background process start","Receipt showing successful connection to 127.0.0.1:6665","Receipt showing the guest login prompt text"],"notes":["Prerequisites such as tool availability are not sufficient for success; the guest prompt must be reachable."]}},{"action":"plan_update","data":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet to 127.0.0.1:6665 reaches the guest login prompt, and leave it running.","current_focus":"Determine available tooling and launch QEMU with a telnet-accessible serial console.","implementation_approach":["Inspect prior receipts and visible state to avoid repeating work.","Use raw_bash to locate qemu and confirm /app/alpine.iso exists.","Launch QEMU in the background with serial redirected to tcp:127.0.0.1:6665,server,nowait or equivalent.","Probe readiness until telnet shows the login prompt."],"validation_strategy":["Confirm the port is listening and telnet connects.","Confirm the guest emits a login prompt, not just boot text.","Keep the VM running after readiness."],"verification_test_strategy":["Use telnet or an equivalent socket probe to connect to 127.0.0.1:6665.","Capture output that includes the login prompt."],"known_bad_behavior":["Launching QEMU without telnet reachability.","Using a different port than 6665.","Stopping the VM after readiness.","Treating ISO presence or process existence as sufficient."],"evidence_gaps":["No receipt-backed evidence yet for QEMU launch or telnet reachability."],"risks":["QEMU may be missing or the ISO may require specific boot parameters.","The guest may need more time to reach the login prompt."],"next_steps":["Inspect environment and start the VM.","Wait for readiness and capture evidence."],"finalization_requirements":["Receipt-backed evidence of launch, telnet connectivity, and login prompt."]}}]}
